package pe.vichaval.gestionriego.agricultor.service;import org.springframework.data.domain.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import pe.vichaval.gestionriego.agricultor.dto.*;import pe.vichaval.gestionriego.agricultor.entity.*;import pe.vichaval.gestionriego.agricultor.repository.*;@Service@Transactional public class AgricultorService{private final AgricultorRepository r;public AgricultorService(AgricultorRepository r){this.r=r;}public Page<Agricultor>listar(String q,int page){return r.buscar(q==null?"":q,PageRequest.of(page,6,Sort.by("apellidos")));}public Agricultor get(Long id){return r.findById(id).orElseThrow();}public void save(AgricultorForm f,Long id){if(id==null&&r.existsByDni(f.getDni()))throw new IllegalArgumentException("DNI ya registrado");if(id!=null&&r.existsByDniAndIdNot(f.getDni(),id))throw new IllegalArgumentException("DNI ya registrado");Agricultor a=id==null?new Agricultor(f):get(id);if(id!=null)a.set(f);r.save(a);}}